#include <bits/stdc++.h>
using namespace std;

using int64 = long long;

const int64 MOD = 1'000'000'007;

int64 modPow(int64 a, int64 p) {
    int64 result = 1;
    while (p > 0) {
        if (p & 1) result = result * a % MOD;
        a = a * a % MOD;
        p >>= 1;
    }
    return result;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int64 f, w, h;
    cin >> f >> w >> h;
    ++h;

    if (w == 0) {
        cout << (f <= 1 ? 1 : 0);
        return 0;
    }

    int64 limit = max(w, f);
    vector<int64> fact(limit + 1), invFact(limit + 1);

    fact[0] = 1;
    for (int64 i = 1; i <= limit; ++i)
        fact[i] = fact[i - 1] * i % MOD;

    invFact[limit] = modPow(fact[limit], MOD - 2);
    for (int64 i = limit; i > 0; --i)
        invFact[i - 1] = invFact[i] * i % MOD;

    auto C = [&](int64 k, int64 n) -> int64 {
        if (k < 0 || k > n || n < 0) return 0;
        return fact[n] * invFact[k] % MOD * invFact[n - k] % MOD;
    };

    auto multiplier = [&](int64 i) -> int64 {
        int64 result = 0;
        if (i > 1 && f >= i - 1)
            result = (result + C(i - 2, f - 1)) % MOD;
        if (f >= i)
            result = (result + 2 * C(i - 1, f - 1)) % MOD;
        if (f >= i + 1)
            result = (result + C(i, f - 1)) % MOD;
        return result;
    };

    int64 okCount = 0;
    int64 total = 0;

    for (int64 i = 1; i <= w / h; ++i) {
        int64 n = w - i * h;
        int64 add = C(i - 1, n + i - 1);
        okCount = (okCount + add * multiplier(i)) % MOD;
    }

    for (int64 i = 1; i <= w; ++i) {
        int64 add = C(i - 1, w - 1);
        total = (total + add * multiplier(i)) % MOD;
    }

    cout << okCount * modPow(total, MOD - 2) % MOD;
    return 0;
}

